   "codice": "extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return

	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Il nodo Player deve essere presente nella scena"):
		return

	var shooter := find_by_name(main, "ShooterEnemy") as StaticBody2D
	if not check("shooter", shooter != null, "Il nodo ShooterEnemy deve essere presente nella scena"):
		return

	await wait_seconds(1.6)
	var found_bullet: bool = false
	for child in main.get_children():
		if child is Area2D and child != shooter.get_node_or_null("StompArea"):
			found_bullet = true
			break
	check("bullet_spawned", found_bullet, "La torretta deve generare e aggiungere un proiettile alla scena allo scadere del timer")

	player.global_position = shooter.global_position + Vector2(0.0, -28.0)
	player.velocity = Vector2(0.0, 200.0)
	await wait_physics_frames(5)

	var bounced: bool = player.velocity.y < 0.0
	var is_destroyed: bool = not is_instance_valid(shooter) or shooter.is_queued_for_deletion()
	if not bounced or not is_destroyed:
		for f in range(10):
			if player.velocity.y < 0.0:
				bounced = true
			if not is_instance_valid(shooter) or shooter.is_queued_for_deletion():
				is_destroyed = true
			if bounced and is_destroyed:
				break
			await wait_physics_frames(1)

	check("player_bounce", bounced, "Saltare sulla torretta dall'alto deve far rimbalzare il giocatore")
	check("shooter_destroyed", is_destroyed, "La torretta deve essere eliminata con queue_free() quando viene schiacciata")
